import{_ as n,a as t}from"./chunks/08-model-settings.wwAq27Vh.js";import{_ as r}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as l,o as a,c as i,a2 as d}from"./chunks/framework.z3u3TMv0.js";const k=JSON.parse('{"title":"Modellverbindung & Parameter","description":"MiniTavern BYOK — Base URL und API Key, Verbindungstest, Sampling; Cloud oder Ollama/LM Studio OpenAI-kompatibel.","frontmatter":{"title":"Modellverbindung & Parameter","description":"MiniTavern BYOK — Base URL und API Key, Verbindungstest, Sampling; Cloud oder Ollama/LM Studio OpenAI-kompatibel.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Modellverbindung & Parameter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK — Base URL und API Key, Verbindungstest, Sampling; Cloud oder Ollama/LM Studio OpenAI-kompatibel."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/manual/model-link"}]]},"headers":[],"relativePath":"de/manual/model-link.md","filePath":"de/manual/model-link.md","lastUpdated":1787224147000}'),o={name:"de/manual/model-link.md"};function s(u,e,g,h,b,m){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="modellverbindung-parameter" tabindex="-1">Modellverbindung &amp; Parameter <a class="header-anchor" href="#modellverbindung-parameter" aria-label="Permalink to &quot;Modellverbindung &amp; Parameter&quot;">​</a></h1><p>BYOK: Schlüssel bleiben in der lokalen sicheren Speicherung; Requests gehen direkt an Ihre Adresse.</p><p>Ohne bezahlte API zuerst <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>; lokale Dienste: <a href="/ultra_guides/de/local/">Lokale Modelle</a>.</p><h2 id="modellverbindung" tabindex="-1">Modellverbindung <a class="header-anchor" href="#modellverbindung" aria-label="Permalink to &quot;Modellverbindung&quot;">​</a></h2><p>Pfad: <strong>Einstellungen → Modelle → Modellverbindung</strong></p><p><img src="'+n+'" alt="Modellverbindungs-Liste"></p><table tabindex="0"><thead><tr><th>Aktion</th><th>Hinweis</th></tr></thead><tbody><tr><td>Neu</td><td>Plattform, Key, Base URL, Modell</td></tr><tr><td>Bearbeiten / Kopieren / Löschen</td><td>Menü rechts in der Liste</td></tr><tr><td>Als Standard</td><td>neue Chats nutzen diese Verbindung</td></tr><tr><td>Testen</td><td>vor dem Speichern oder auf der Bearbeiten-Seite. Es muss ein <strong>Text-Chat</strong>-Modell sein; TTS-/Bild-IDs (z. B. Gemini <code>*-tts</code>) melden fehlende Textunterstützung — siehe <a href="/ultra_guides/de/manual/errors#textoutputunsupported">Fehler · textOutputUnsupported</a></td></tr></tbody></table><h3 id="plattformtypen-haufig" tabindex="-1">Plattformtypen (häufig) <a class="header-anchor" href="#plattformtypen-haufig" aria-label="Permalink to &quot;Plattformtypen (häufig)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option (App-Text gilt)</th><th>Zweck</th></tr></thead><tbody><tr><td>Cloud-Presets</td><td>Base URL für CN-/Intl.-Sites vorausgefüllt</td></tr><tr><td>Custom (OpenAI)</td><td>lokales Ollama / LM Studio, kompatible Gateways</td></tr><tr><td>Custom Gemini / Anthropic</td><td>jeweilige Protokoll-Endpunkte</td></tr></tbody></table><p>Mehrstandort-Plattformen: «Internationale Site» umschaltbar. Lokal: <a href="/ultra_guides/de/connect-app/minitavern">In MiniTavern verbinden</a> · <a href="/ultra_guides/de/local/tools">Tool-Übersicht</a>.</p><p><img src="'+r+'" alt="Neue Verbindung"></p><h2 id="modelleinstellungen-globale-parameter" tabindex="-1">Modelleinstellungen (globale Parameter) <a class="header-anchor" href="#modelleinstellungen-globale-parameter" aria-label="Permalink to &quot;Modelleinstellungen (globale Parameter)&quot;">​</a></h2><p>Pfad: <strong>Einstellungen → Modelleinstellungen</strong></p><p><img src="'+t+'" alt="Modelleinstellungen"></p><p>Häufige Felder (Namen laut App):</p><ul><li>Gedächtnislänge (bezogen auf Verlaufseinträge)</li><li>Antwort-Token (max tokens, obergrenze 128000; bei manchen Claude-Szenarien <strong>nicht</strong> auf None)</li><li>Temperature, Top-P / Top-K</li><li>Streaming an/aus</li></ul><h2 id="sitzungsubersteuerung" tabindex="-1">Sitzungsübersteuerung <a class="header-anchor" href="#sitzungsubersteuerung" aria-label="Permalink to &quot;Sitzungsübersteuerung&quot;">​</a></h2><p>Pfad: Chat → <strong>Einstellungen</strong> → Modellverbindung / Parameter</p><p>Pro Chat eigene Verbindung und Sampling — ohne globale Defaults zu ändern.</p><h2 id="bilderkennung-in-den-chat-einstellungen" tabindex="-1">Bilderkennung in den Chat-Einstellungen <a class="header-anchor" href="#bilderkennung-in-den-chat-einstellungen" aria-label="Permalink to &quot;Bilderkennung in den Chat-Einstellungen&quot;">​</a></h2><p>Pfad: <strong>Einstellungen → Chat → Bilderkennung</strong></p><p>Pro Chat unter Chat-Einstellungen → <strong>Bilderkennung &amp; Anzeige</strong> Defaults folgen oder einzeln überschreiben (Beschreibungsmodell und Prompts bleiben global).</p><ul><li>«Bildbeschreibung» aus: Multimodal sendet Bilder direkt (Modell braucht Vision).</li><li>An: greift nur, wenn das aktuelle Chat-Hauptmodell <strong>keine</strong> Bildparameter unterstützt — zuerst Beschreibungsmodell Bild→Text (kann mit Personenerkennung in einem Request laufen), dann Hauptmodell; Ergebnisse werden gecacht. Unterstützt das Hauptmodell Vision, bleibt Multimodal-Direktübertragung — der Schalter greift nicht.</li></ul><p>Reihenfolge ohne Vision + Beschreibung an: Beschreibung (+ Person) → Hauptchat (bei intelligentem/Keyword-Auto-Bild ggf. mit Bildprompt) → bei Bilddaten Bypass-Bildgenerierung.</p><p>Bei «Modell unterstützt keine Bilder»: <a href="/ultra_guides/de/manual/errors#visionunsupported">Fehler · visionUnsupported</a>.</p><h2 id="bildgenerierung-verbindung-antwortbilder-schlusselworter" tabindex="-1">Bildgenerierung (Verbindung / Antwortbilder / Schlüsselwörter) <a class="header-anchor" href="#bildgenerierung-verbindung-antwortbilder-schlusselworter" aria-label="Permalink to &quot;Bildgenerierung (Verbindung / Antwortbilder / Schlüsselwörter)&quot;">​</a></h2><p>Pfad: <strong>Einstellungen → Bildgenerierung</strong></p><ul><li><strong>Bildverbindung / Bildeinstellungen</strong>: API, Größe/Qualität, Anzahl (nur <code>/imagine</code>), Enhance/Negativprompts (nur <code>/imagine</code> und Anhang-Menü; Standard-Qualitätswörter / Low Quality · Blur · Extra Fingers · Wasserzeichen usw.)</li><li><strong>Antwortbilder</strong> (in Bildeinstellungen): Schalter an, dann Auslöser wählen. Aus = kein Auto-Bild im Chat (Slash, Anhang-Menü, langes Drücken auf Bubbles bleiben) <ul><li><strong>Intelligente Entscheidung</strong>: Modell entscheidet pro Runde; Aspect Ratio nach Szene (Selfie 3:4, Kamera 3:2), bei Treffer fest 1 Bild. Anhang möglich (z. B. «in diesem Stil»); Anhang = Stilreferenz, ersetzt keine Charakter-/User-Identitätsbilder</li><li><strong>Keyword-Auslöser</strong>: Nutzertext trifft Keyword-Regel (Anhang möglich); Motiv/Aspect Ratio aus dem Dialog, fest 1 Bild</li></ul></li><li><strong>Keyword-Regeln</strong>: Regeln konfigurieren. Wirklich auslösen nur, wenn Antwortbilder an und Keyword gewählt ist</li></ul><p>Bildgenerierung im Chat:</p><table tabindex="0"><thead><tr><th>Einstieg</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>/imagine Prompt</code></td><td>Hauptmodell prüft zuerst Bezug zum Dialog und ob Charakter-/User-Referenz nötig ist, baut dann den Prompt. Anhänge über Plus: Hauptmodell sieht sie beim Schreiben; bei der Generierung als Referenz; Anhänge überspringen die Charakter-/User-Entscheidung nicht. Anhänge erscheinen als kleine Vorschau in der Bild-Bubble, nicht als Chat-Nachricht. Anzahl aus «Generierungsanzahl». Bei Fehler bleibt die Bubble mit Retry</td></tr><tr><td><code>/imagine scene</code> / Anhang → Nach Story</td><td>aktuelle Szene aus dem kürzlichen Dialog, 1 Bild</td></tr><tr><td><code>/imagine last</code> / Anhang → Nach letzter Nachricht</td><td>nach letzter Nachricht, 1 Bild</td></tr><tr><td>Anhang → Hintergrundbild</td><td>Umgebungshintergrund, 1 Bild; danach als Chat-Hintergrund setzbar</td></tr><tr><td>Lang drücken → Bild</td><td>nach dieser Bubble, 1 Bild</td></tr></tbody></table><p>Ohne Bildverbindung: die vier Anhang-Modi und <code>/imagine</code> öffnen «Zu Einstellungen / Abbrechen», Eingabe bleibt. Intelligent/Keyword ohne Verbindung: Toast. Antwortbilder-Schalter ohne Verbindung: Modal, Schalter bleibt aus.</p><p>Beispiel: «Schick ein Selfie von dir» nutzt Charakterreferenz und Kontext; «Foto eines Hundes» ist eine unabhängige Anfrage ohne Charaktergesicht.</p><p>Lokal A1111 / ComfyUI: <a href="/ultra_guides/de/local/image-gen/">Bildmodelle lokal</a> · <a href="/ultra_guides/de/local/image-gen/connect-app">App verbinden</a>.<br> Cloud-Free: <a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Cloud · Bild</a>.</p><h2 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h2><p>Verbindungstest oder Chat fehlgeschlagen → Toast / Bubble → <strong>Details</strong> (Code + Ursache + Vorschlag) → <a href="/ultra_guides/de/manual/errors">Fehlercodes</a>.</p>',35)])])}const B=l(o,[["render",s]]);export{k as __pageData,B as default};
